import pathlib,json,hashlib,base64,subprocess,os,time
r=pathlib.Path('/content/mathvisionkid_skill_recovery_150m_20261024')
assert skill_training_process.poll()==0 and skill_fewshot_process.poll()==0
assert not globals().get('skill_final_process') or skill_final_process.poll() is not None
assert not (r/'final_eval').exists(),'One-time final inference must not have begun'
payload={'final_evaluation_worker_v2.py': '', 'test_final_evaluation_worker_v2.py': '', 'fewshot_selection.json': '', 'root_fewshot_semantic_review.json': '', 'locked_test_binding.json': ''};pins={'final_evaluation_worker_v2.py': '6c24b662d7eaf4ea0d464f1de6c490a0ada68792006e0fb3f9f29885b8d50f63', 'test_final_evaluation_worker_v2.py': 'db99487555735b7ce5e1e1217d2086d4299572135038cdf84a0f41f2bac9b11a', 'fewshot_selection.json': '6e082f5ce079fe2a85ccd35ae0f203d5d40172545938fe7a5494c1ab9139c36a', 'root_fewshot_semantic_review.json': '7535c65fd9afd107bf4be0d7f0a7805aaea20b65bc91eee2b969c91fd9e7d492', 'locked_test_binding.json': '34a7fdfbb573ccb3203d5f2d4a0d501c46a9f3c5e2e524b92d042f32a59a6a70'}
for n,v in payload.items():
 b=base64.b64decode(v);assert hashlib.sha256(b).hexdigest()==pins[n]
 if (r/n).exists():assert (r/n).read_bytes()==b,'Preserve existing evidence: '+n
 else:(r/n).write_bytes(b)
env={**os.environ,'TOKENIZERS_PARALLELISM':'false','PYTHONPATH':str(r)}
check=subprocess.run([str(r/'venv/bin/python'),'-c',"import pathlib,json\nimport final_evaluation_worker_v2 as F\nr=pathlib.Path('/content/mathvisionkid_skill_recovery_150m_20261024')\nscope=F.R.load_scope(r);fixtures,sha=F.verify_fixture_bundle(r,scope)\ndev=F.read_rows(r/'new_validation_candidates.jsonl');dsha=F.sha(r/'new_validation_candidates.jsonl')\nselected=F.verify_selection(r,scope,dev,dsha)\ncontext=F.verify_fewshot_selection(r,dev,dsha,selected['baseline_output_sha256'])\npackages=F.check_environment(r)\nprint(json.dumps({'preflight_passed':True,'selected_kind':selected['selected_kind'],'mode_selection':context['mode_selection'],'locked_fixture_count':len(fixtures),'locked_sha256':sha,'no_generation_performed':True,'packages':packages}))\n"],env=env,capture_output=True,text=True,timeout=50)
assert check.returncode==0,check.stdout[-2000:]+'\n'+check.stderr[-4000:]
print(check.stdout)
assert time.time()<json.loads((r/'owner_run_scope.json').read_bytes())['hard_deadline_unix']-2100
skill_final_process=subprocess.Popen([str(r/'venv/bin/python'),'-u',str(r/'final_evaluation_worker_v2.py'),'--root',str(r)],stdout=(r/'final_eval.log').open('ab',buffering=0),stderr=subprocess.STDOUT,env=env)
(r/'final_launch_pins.json').write_text(json.dumps({'files':pins,'started_unix':time.time(),'pid':skill_final_process.pid,'one_time_test':True},indent=2)+'\n')
print(json.dumps({'final_evaluation_launched':True,'pid':skill_final_process.pid,'source_training_exited':True,'once_after_dev_selection':True,'test_used_to_reselect':False,'no_optimizer_loaded':True}))
